+        mode = typeof parsed.mode === "string" ? parsed.mode : "";
+    }
+    catch {
+        // (fail closed: no opt-in)
+    }
+    return { optIn, mode: process.env.LOA_HEADLESS_MODE || mode || "prefer-api" };
+}
